cd /app/work && python3 - <<'PYEOF'
import json, subprocess, sys, importlib.util, copy
spec = importlib.util.spec_from_file_location("vt", "/app/work/valid_tests.py")
vt = importlib.util.module_from_spec(spec); sys.argv=["vt"]; spec.loader.exec_module(vt)
names=["whitespace","crlf","tabs inside","zero demand no paths","all edges failed","opposite edges","repeated comm pair","demand 1024","768 paths ok boundary"]
for name in names:
    for nm,expect,mutate,raw in vt.cases:
        if nm==name:
            if raw is None:
                r=copy.deepcopy(vt.BASE); mutate(r); raw=json.dumps(r).encode()+b"\n"
            else:
                raw = raw if raw.endswith(b"\n") else raw+b"\n"
            p=subprocess.run([sys.executable,'/app/submission/planner.py'],input=raw,capture_output=True)
            print(nm, "->", p.stdout.decode().strip()[:120], "| stderr:", p.stderr.decode()[:200])
            break
PYEOF
